const [lang,setLang]=useState(0),[me,setMe]=useState<any>(null),[ready,setReady]=useState(false),[page,setPage]=useState('dashboard'),[shop,setShop]=useState(()=>typeof window!=='undefined'?localStorage.getItem('osp_shop')||'':''),[data,setData]=useState<any>({}),[query,setQuery]=useState(''),[modal,setModal]=useState<any>(null),[form,setForm]=useState<any>({}),[busy,setBusy]=useState(false),[toast,setToast]=useState(''),[error,setError]=useState(''),[nav,setNav]=useState(false),[makes,setMakes]=useState(commonMakes),[models,setModels]=useState<string[]>([]),[view,setView]=useState('board'),[formStack,setFormStack]=useState<any[]>([]),[partsCatalog,setPartsCatalog]=useState<any>({parts:[],suppliers:[],categories:[]}),[techContext,setTechContext]=useState<any>({}),[workbenchOverlay,setWorkbenchOverlay]=useState(false),[techOverlay,setTechOverlay]=useState(false),[techDirty,setTechDirty]=useState(false),[theme,setTheme]=useState(()=>typeof window!=='undefined'?localStorage.getItem('osp_theme_v2')==='light'?'light':'dark':'dark');
