async function api(action:string,body?:any,extra='',selectedShop=shop){const r=await fetch('/api/'+action+'?shop='+encodeURIComponent(selectedShop)+extra,{method:body?'POST':'GET',credentials:'include',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(['login','signup','logout'].includes(action)?{...body,embedded}:body):undefined});const d:any=await r.json();if(!r.ok){if(r.status===402){setMe((m:any)=>m?{...m,access:false}:m);setData({});setModal(null);}throw Error(d.error||'Request failed');}return d;}
function msg(s:string){setToast(s);setTimeout(()=>setToast(''),4000);}
async function load(selectedShop=shop,requireSession=false){try{const m=await api('me',undefined,'',selectedShop);setMe(m);if(m.access){const keys=Object.keys(schema);const result=await Promise.all(keys.map(async k=>[k,await api(k==='users'?(m.user.role==='employee'?'team':'users'):'records',undefined,k==='users'?'':'&table='+k,selectedShop)]));setData(Object.fromEntries(result));}else setData({});}catch(e:any){if(e.message==='Please sign in'){setMe(null);if(requireSession)throw Error(t('Your browser did not keep the session in this preview. Open the app in a new tab and sign in there.','El navegador no guardó la sesión en esta revisión. Abra el programa en una pestaña nueva e ingrese allí.'));}else if(requireSession)throw e;else setError(e.message);}finally{setReady(true);}}
