useEffect(()=>{if(!me||root||!me.access||!me.accessUntil)return;const remaining=me.accessUntil-Date.now();const timer=setTimeout(()=>{setData({});setModal(null);load();},Math.max(0,Math.min(remaining+100,2147483647)));return()=>clearTimeout(timer);},[me?.accessUntil,me?.access,root]);
useEffect(()=>{if(!me)return;const p=new URLSearchParams(location.search);if(p.get('session_id')){api('verify-payment',{session:p.get('session_id')}).then(()=>{history.replaceState({},'',location.pathname);msg(t('Subscription activated','Suscripción activada'));load();}).catch(e=>setError(e.message));}},[me?.user.id]);
async function run(fn:()=>Promise<any>){setBusy(true);setError('');try{await fn();}catch(e:any){setError(e.message);}finally{setBusy(false);}}
async function signupWorkshop(payload:any){run(async()=>{await api('signup',payload);setSignup(false);setShop('');localStorage.removeItem('osp_shop');setPage('dashboard');await load('',true);msg(t('Your 7-day trial has started. Welcome!','Su prueba de 7 días ha comenzado. ¡Bienvenido!'));});}
async function login(e:any){e.preventDefault();const credentials=Object.fromEntries(new FormData(e.currentTarget));run(async()=>{await api('login',credentials,'','');localStorage.removeItem('osp_shop');setShop('');setPage('dashboard');setSignup(false);setData({});await load('',true);});}
function open(k:string,r:any={}){setFormStack([]);setError('');setModels([]);setModal(k);setForm({...((k==='workorders')?{status:'Draft',category:'Mechanical',date:new Date().toISOString().slice(0,10),tax:me?.shop.profile.tax||0}:k==='purchases'?{status:'Draft',date:new Date().toISOString().slice(0,10)}:k==='services'?{date:new Date().toISOString().slice(0,10)}:{}),...r});}
function addRelated(table:string,record:any={},stagedIndex:number|null=null){if(busy)return;setFormStack(stack=>[...stack,{modal,form,stagedIndex}]);setModal(table);setForm(table==='vehicles'?{year:new Date().getFullYear(),customer:modal==='customers'?form.id||'':form.customer||'',...record}:record);setModels([]);setError('');}
function closeForm(){if(busy)return;const parent=formStack.at(-1);if(parent){setModal(parent.modal);setForm(parent.form);setFormStack(s=>s.slice(0,-1));}else{setModal(null);setFormStack([]);}setError('');}
function selectCustomer(customer:string){setForm((f:any)=>{const vehicle=(data.vehicles||[]).find((v:any)=>v.id===f.vehicle);return {...f,customer,...(vehicle?.customer&&vehicle.customer!==customer?{vehicle:''}:{})};});}
function selectVehicle(vehicle:string){const row=(data.vehicles||[]).find((v:any)=>v.id===vehicle);setForm((f:any)=>({...f,vehicle,customer:row?.customer||f.customer||''}));}
async function save(e:any){e.preventDefault();if(logoReading||busy)return;const parent=formStack.at(-1);if(modal==='vehicles'&&parent?.modal==='customers'&&!parent.form.id){const vehicles=[...(parent.form._pendingVehicles||[])];if(parent.stagedIndex===null)vehicles.push({...form,customer:undefined});else vehicles[parent.stagedIndex]={...form,customer:undefined};setModal('customers');setForm({...parent.form,_pendingVehicles:vehicles});setFormStack(s=>s.slice(0,-1));setError('');return;}
run(async()=>{const {_pendingVehicles,...payload}=form;let result:any;if(modal==='shops')result=await api('shops',payload);else if(modal==='users')result=await api('users',payload);else result=await api('records',{table:modal,id:payload.id,data:payload,...(modal==='customers'?{vehicles:_pendingVehicles||[]}: {})});
const saved={...payload,id:result.id};if(['customers','vehicles'].includes(modal))setData((d:any)=>({...d,[modal]:[saved,...(d[modal]||[]).filter((r:any)=>r.id!==saved.id)],...(result.vehicles?.length?{vehicles:[...result.vehicles,...(d.vehicles||[])]}:{})}));
if(parent){let restored={...parent.form};if(modal==='customers'){restored.customer=result.id;if(parent.modal==='workorders'&&result.vehicles?.length)restored.vehicle=result.vehicles[0].id;else if(parent.modal==='workorders')restored.vehicle='';}if(modal==='vehicles'&&parent.modal!=='customers')restored={...restored,vehicle:result.id,customer:payload.customer||restored.customer||''};setModal(parent.modal);setForm(restored);setFormStack(s=>s.slice(0,-1));}else{setModal(null);setFormStack([]);}await load();msg(parent?t('Registered and selected. Continue your form.','Registrado y seleccionado. Continúe su formulario.'):t('Saved successfully','Guardado correctamente'));});}
async function remove(k:string,r:any){if(!confirm(t('Delete this record?','¿Eliminar este registro?')))return;run(async()=>{await api('records',{table:k,id:r.id,delete:true});await load();msg(t('Record deleted','Registro eliminado'));});}
async function catalog(kind:string){run(async()=>{const d=await api('catalog',undefined,'&kind='+kind+'&make='+encodeURIComponent(form.make||'')+'&year='+encodeURIComponent(form.year||'')+'&vin='+encodeURIComponent(form.vin||''));if(kind==='makes'){setMakes([...new Set<string>([...commonMakes,...d.Results.map((r:any)=>r.Make_Name)])].sort());msg(t('NHTSA makes loaded','Marcas NHTSA cargadas'));}if(kind==='models'){setModels([...new Set<string>(d.Results.map((r:any)=>r.Model_Name))].sort());msg(t('Models loaded. Select a model or enter manually.','Modelos cargados. Seleccione o escriba manualmente.'));}if(kind==='vin'){const v=d.Results[0];setForm((f:any)=>({...f,make:v.Make||f.make,model:v.Model||f.model,year:v.ModelYear||f.year,engine:[v.DisplacementL,v.EngineCylinders&&v.EngineCylinders+' cyl',v.FuelTypePrimary].filter(Boolean).join(' / '),trim:v.Trim||f.trim}));msg(v.ErrorText||'VIN decoded');}});}
