if(k==='customer'||k==='vehicle'){const records=(data[refs[k]]||[]).filter((r:any)=>k!=='vehicle'||!form.customer||r.customer===form.customer||r.id===form.vehicle);return <div className="related-field" key={k}><label htmlFor={'f-'+k}>{L(k)}</label><div className="related-select"><select id={'f-'+k} value={form[k]||''} required={['vehicles','workorders'].includes(modal)} onChange={e=>k==='customer'?selectCustomer(e.target.value):selectVehicle(e.target.value)}><option value="">{t('Select…','Seleccionar…')}</option>{records.map((r:any)=><option key={r.id} value={r.id}>{k==='customer'?[r.name,r.phone].filter(Boolean).join(' · '):[r.year,r.make,r.model,r.plate].filter(Boolean).join(' · ')}</option>)}</select><button type="button" className="secondary related-add" disabled={busy} aria-label={k==='customer'?t('Add customer','Agregar cliente'):t('Add vehicle','Agregar vehículo')} onClick={()=>addRelated(refs[k])}><Plus size={18}/><span>{t('Add','Agregar')}</span></button></div><p className="field-help">{!records.length?(k==='customer'?t('No customers registered. Use + Add to register one here.','No hay clientes registrados. Use + Agregar para registrar uno aquí.'):form.customer?t('This customer has no registered vehicles. Use + Add.','Este cliente no tiene vehículos registrados. Use + Agregar.'):t('No vehicles available. Use + Add to register one.','No hay vehículos disponibles. Use + Agregar para registrar uno.')):k==='vehicle'&&form.customer?t('Vehicles belonging to the selected customer.','Vehículos del cliente seleccionado.'):t('Choose a record or use + Add without leaving this form.','Seleccione un registro o use + Agregar sin salir de este formulario.')}</p></div>;}
if(refs[k])control=<select {...inputProps}><option value="">{t('Select…','Seleccionar…')}</option>{(data[refs[k]]||[]).map((r:any)=><option value={r.id} key={r.id}>{r.name||r.title||[r.year,r.make,r.model].join(' ')}</option>)}</select>;
else if(k==='bodyType')control=<select {...inputProps}><option value="">{t('Auto-detect from class','Detectar desde clase')}</option>{[['car','Car','Auto'],['suv','SUV','SUV'],['truck','Pickup truck','Camioneta pickup'],['van','Van / minivan','Van / minivan']].map(([id,en,es])=><option value={id} key={id}>{t(en,es)}</option>)}</select>;
