const columns:any={workorders:['title','customer','vehicle','status','due'],customers:['name','phone','email'],vehicles:['make','model','year','vin','customer'],inventory:['name','sku','quantity','reorder','price'],suppliers:['name','phone','email'],services:['title','vehicle','date','mileage'],purchases:['title','supplier','status','quantity','cost'],diagrams:['title','category','source','url'],users:['name','username','role','active']};
function status(v:string){return <span className={'badge '+(v==='Completed'||v==='Delivered'||v==='Received'?'good':v==='In progress'||v==='Paint booth'?'progress':'')}>{tr(v)||'—'}</span>;}
function orderCard(r:any){return <button className="order-card" key={r.id} onClick={()=>open('workorders',r)}><div className="row"><span className="mono">#{r.id.slice(0,6).toUpperCase()}</span><ArrowUpRight size={16}/></div><h3>{r.title}</h3><p><Car size={14}/>{label('vehicle',r.vehicle)}</p><div className="row"><span>{label('customer',r.customer)}</span><strong>{money(total(r))}</strong></div><footer><span>{r.due||t('No due date','Sin fecha límite')}</span><span className="avatar tiny">{(label('employee',r.employee)||'T').slice(0,2).toUpperCase()}</span></footer></button>;}
function table(k:string,rs:any[]){return <div className="table-scroll"><table><thead><tr>{(columns[k]||[]).map((c:string)=><th key={c}>{L(c)}</th>)}<th/></tr></thead><tbody>{rs.map(r=><tr key={r.id}>{(columns[k]||[]).map((c:string)=><td key={c}>{refs[c]?label(c,r[c]):c==='status'?status(r[c]):['price','cost'].includes(c)?money(r[c]):c==='active'?r.active?t('Active','Activo'):t('Disabled','Desactivado'):c==='url'&&r.url?<a href={r.url} target="_blank" rel="noreferrer">{t('Open reference','Abrir referencia')} ↗</a>:r[c]||'—'}</td>)}<td><div className="actions">{k==='workorders'&&<button className="icon-btn" aria-label={t('Technical help','Ayuda técnica')} onClick={()=>{setTechContext({workorderId:r.id,vehicleId:r.vehicle||''});setPage('technical');}}><BookOpen size={15}/></button>}<button className="icon-btn" aria-label="Edit" onClick={()=>open(k,r)}><Pencil size={15}/></button>{k==='workorders'&&<button className="icon-btn" aria-label="Print" onClick={()=>{setModal('print');setForm(r);}}><Printer size={15}/></button>}{manager&&k!=='users'&&<button className="icon-btn danger" aria-label="Delete" onClick={()=>remove(k,r)}><Trash2 size={15}/></button>}</div></td></tr>)}</tbody></table>{!rs.length&&<div className="empty"><Package size={30}/><h3>{t('A fresh start for your workshop','Un nuevo comienzo para su taller')}</h3><p>{t('Add your first record to keep everything organized.','Agregue su primer registro para organizar todo.')}</p><button className="primary" onClick={()=>open(k)}><Plus size={16}/>{t('Add record','Agregar registro')}</button></div>}</div>;}
