{page==='dashboard'&&<><div className="stats">{[[t('Active work orders','Órdenes activas'),active.length,ClipboardList,t('Across your workshop','En todo su taller')],[t('Vehicles registered','Vehículos registrados'),data.vehicles?.length||0,Car,t('Customer vehicles','Vehículos de clientes')],[t('Open order value','Valor de órdenes abiertas'),money(active.reduce((a:number,r:any)=>a+total(r),0)),Activity,t('Labor, parts & tax','Mano de obra, partes e impuestos')],[t('Low stock alerts','Alertas de inventario'),low.length,Package,t('Items at reorder level','Artículos en nivel mínimo')]].map(([title,value,I,sub]:any,i)=><div className={'stat stat-'+i} key={title}><div className="row"><span>{title}</span><I size={19}/></div><strong>{value}</strong><small>{sub}</small></div>)}</div><div className="dashboard-grid"><section className="panel"><div className="panel-header"><div><h2>{t('Workshop activity','Actividad del taller')}</h2><p>{t('Your latest jobs, from intake to handover.','Sus trabajos recientes, de recepción a entrega.')}</p></div><button className="text-btn" onClick={()=>setPage('workorders')}>{t('View all','Ver todas')}<ArrowUpRight size={15}/></button></div>{orders.length?<div className="latest-list">{orders.slice(0,5).map((r:any)=><button key={r.id} onClick={()=>open('workorders',r)}><div className={'job-icon '+(r.category==='Body & paint'?'paint':'')} >{r.category==='Body & paint'?<Paintbrush size={20}/>:<Wrench size={20}/>}</div><div><strong>{r.title}</strong><small>{label('vehicle',r.vehicle)} · {label('customer',r.customer)}</small></div>{status(r.status)}<strong>{money(total(r))}</strong><ArrowUpRight size={16}/></button>)}</div>:<div className="empty workshop-empty"><div className="empty-art"><Car size={55} strokeWidth={1}/><span><Check size={18}/></span></div><h3>{t('Ready for your first work order','Listo para su primera orden')}</h3><p>{t('Add a customer and vehicle, then bring the job into your workflow.','Agregue un cliente y vehículo, luego incorpore el trabajo a su flujo.')}</p><button className="secondary" onClick={()=>open('customers')}>{t('Add a customer','Agregar un cliente')}<ArrowRight size={15}/></button></div>}<div className="workflow-footer">{[t('Intake','Recepción'),t('Repair & paint','Reparación y pintura'),t('Quality check','Control de calidad'),t('Delivery','Entrega')].map((v,i)=><span key={v}><i>{i+1}</i>{v}{i<3&&<ArrowRight size={13}/>}</span>)}</div></section><div className="dashboard-side"><section className="green-card"><span className="eyebrow">{t('A BETTER WAY TO WORK','UNA MEJOR FORMA DE TRABAJAR')}</span><h2>{t('Every detail.\nOne workspace.','Cada detalle.\nUn solo espacio.')}</h2><p>{t('Keep your team aligned, from the service bay to the paint booth.','Su equipo conectado, desde el área de servicio hasta la cabina de pintura.')}</p><button onClick={()=>setPage(manager?'users':'vehicles')}>{t('Manage your workspace','Gestionar su espacio')}<ArrowUpRight size={18}/></button><Wrench className="decor" size={125} strokeWidth={.7}/></section><section className="panel stock-panel"><div className="panel-header"><h2>{t('Parts to watch','Repuestos por revisar')}</h2><Package size={18}/></div>{low.length?low.slice(0,3).map((r:any)=><button className="stock-item" key={r.id} onClick={()=>open('inventory',r)}><span>{r.name}</span><span className="badge">{r.quantity} {t('left','restantes')}</span></button>):<div className="stock-clear"><CheckCircle2 size={21}/><span>{t('No low stock items','Sin artículos en nivel bajo')}<small>{t('Inventory alerts appear here','Las alertas aparecerán aquí')}</small></span></div>}</section></div></div><section className="quick-links">{[['customers',t('Customer relationships','Relaciones con clientes'),t('People behind every vehicle','Las personas detrás de cada vehículo')],['vehicles',t('Vehicle intelligence','Información vehicular'),t('VIN lookup & vehicle details','Consulta VIN y datos del vehículo')],['technical',t('Technician help','Ayuda al técnico'),t('Videos, diagrams & technical tools','Videos, diagramas y herramientas')]].map(([k,title,sub])=>{const I=icons[k];return <button key={k} onClick={()=>setPage(k)}><I size={23}/><div><strong>{title}</strong><small>{sub}</small></div><ArrowUpRight size={17}/></button>;})}</section></>}
