{page==='billing'&&manager&&!root&&<div className="billing-grid"><div className="plan-card"><span className="eyebrow green">OSP AUTOCARE / WORKSHOP</span><h2>{t('Everything your shop needs.','Todo lo que su taller necesita.')}</h2><div className="plan-price">$49.99<span>/ {t('month','mes')}</span></div><p>{t('USD · Billed monthly · One independent workshop','USD · Cobro mensual · Un taller independiente')}</p>{[t('Your moderator + employee accounts','Su moderador + cuentas de empleados'),t('Mechanical, body & paint work orders','Órdenes de mecánica, carrocería y pintura'),t('Customers, vehicles & VIN lookup','Clientes, vehículos y consulta VIN'),t('Inventory, purchases & service history','Inventario, compras e historial de servicio'),t('English & Spanish interface','Interfaz en inglés y español')].map(v=><div className="plan-feature" key={v}><CheckCircle2 size={18}/>{v}</div>)}<button className="primary full" disabled={busy||me.shop.id==='demo'} onClick={()=>run(async()=>{const r=await api('subscribe',{});location.href=r.url;})}>{t('Subscribe now · $49.99/month','Suscribirse ahora · $49.99/mes')}<ArrowRight size={17}/></button>{me.shop.subscription_id&&<button className="secondary full" onClick={()=>run(async()=>{const r=await api('portal',{});location.href=r.url;})}>{t('Manage / cancel subscription','Gestionar / cancelar suscripción')}</button>}{me.platformPayment.direct&&<a className="secondary full" target="_blank" rel="noreferrer" href={me.platformPayment.direct}>{t('Pay with Autobooks','Pagar con Autobooks')}<ArrowUpRight size={16}/></a>}<small>{t('Subscribing now starts paid billing immediately.','Al suscribirse ahora, el cobro comienza inmediatamente.')}</small><small>{t('External payments require OSP confirmation.','Los pagos externos requieren confirmación de OSP.')}</small></div><section className="panel billing-info"><ShieldCheck size={32}/><h2>{t('Your workshop subscription','La suscripción de su taller')}</h2><p>{me.shop.name}</p>{status(me.status==='paid'?'Approved':'Draft')}<h3>{me.status==='trial'?t('Free trial active','Prueba gratuita activa'):me.status==='paid'?t('Paid access active','Acceso pagado activo'):me.status==='disabled'?t('Disabled','Desactivado'):t('Subscription required','Suscripción requerida')}</h3>{me.trialUntil>0&&<p>{t('Free trial ends: ','La prueba gratuita termina: ')}{new Date(me.trialUntil).toLocaleString(lang?'es-US':'en-US')}</p>}<p>{me.shop.paid_until?t('Paid access until: ','Acceso pagado hasta: ')+new Date(me.shop.paid_until).toLocaleString(lang?'es-US':'en-US'):t('No payment yet. No automatic charge without subscribing.','Sin pago aún. No hay cobro automático hasta suscribirse.')}</p><hr/><h3>{t('Payment configuration','Configuración de pagos')}</h3><p>{t('OSP payment settings collect the platform subscription. Moderator settings belong to their own workshop. Secret keys are encrypted and never returned to the browser.','La configuración de OSP cobra la suscripción de la plataforma. La del moderador corresponde a su propio taller. Las claves secretas se cifran y nunca se devuelven al navegador.')}</p><button className="secondary" onClick={()=>setPage('settings')}>{t('Open payment settings','Abrir configuración de pagos')}<ArrowRight size={15}/></button>{me.shop.id==='demo'&&<p className="notice">{t('Demo workspace: create a workshop to test its subscription.','Espacio demo: cree un taller para probar su suscripción.')}</p>}</section></div>}
{page==='settings'&&<div className="settings-grid">{manager&&<><section className="panel settings-card"><div className="section-title"><Building2/><div><h2>{t('Business profile','Perfil del negocio')}</h2><p>{t('Your identity on every work order.','Su identidad en cada orden de trabajo.')}</p></div></div><form key={me.shop.id} onSubmit={e=>{e.preventDefault();if(logoReading)return;const f=Object.fromEntries(new FormData(e.currentTarget));run(async()=>{await api('profile',{...me.shop.profile,...f});load();msg(t('Business profile saved','Perfil guardado'));});}}><label>{L('name')}<input name="name" defaultValue={me.shop.name} required/></label><BusinessIdentityFields lang={lang} value={me.shop.profile} onReading={setLogoReading} onChange={profile=>setMe({...me,shop:{...me.shop,profile}})}/><label>{L('tax')}<input name="tax" type="number" min="0" max="100" step=".01" defaultValue={me.shop.profile.tax||0}/></label><button className="primary" disabled={busy||logoReading}>{t('Save profile','Guardar perfil')}</button><button type="button" className="secondary full" onClick={()=>open('print',{id:'SAMPLE-001',_preview:true,title:t('Brake service · example','Servicio de frenos · ejemplo'),date:new Date().toISOString().slice(0,10),labor:120,parts:0,tax:me.shop.profile.tax||0,lineItems:[{name:'Front brake pad set',partEs:'Juego de pastillas de freno delanteras',condition:'New',quantity:1,unitPrice:89.99}]})}>{t('Preview customer invoice / PDF','Vista previa de factura / PDF')}</button></form></section><section className="panel settings-card"><div className="section-title"><CreditCard/><div><h2>{t('Payment methods','Métodos de pago')}</h2><p>{root?t('Platform subscription collection','Cobro de suscripciones de la plataforma'):t('Your workshop payment credentials','Credenciales de pago de su taller')}</p></div></div><form onSubmit={e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));run(async()=>{await api('payment-settings',f);(e.target as HTMLFormElement).reset();await load();msg(t('Payment settings saved','Métodos de pago guardados'));});}}><label>{t('Stripe publishable key','Clave pública Stripe')}<input name="publicKey" defaultValue={me.payment.publicKey} placeholder="pk_test_… / pk_live_…"/></label><label>{t('Stripe secret key','Clave secreta Stripe')}<input name="secret" type="password" autoComplete="new-password" placeholder={me.payment.hasSecret?t('Saved securely · leave blank to keep','Guardada · deje vacío para conservar'):'sk_test_… / sk_live_…'}/></label>{root&&<label>{t('Stripe webhook signing secret','Secreto de firma webhook Stripe')}<input name="webhook" type="password" placeholder={me.payment.hasWebhook?t('Saved securely','Guardado de forma segura'):'whsec_…'}/></label>}<label>{t('Autobooks direct payment link','Enlace directo de pago Autobooks')}<input type="url" name="direct" defaultValue={me.payment.direct} placeholder="https://…"/></label><button className="primary" disabled={busy}>{t('Save payment methods','Guardar métodos de pago')}</button></form><div className="notice">{root?t('Webhook endpoint:','Endpoint webhook:'):t('Workshop credentials are separate from the OSP subscription account.','Las credenciales del taller son independientes de la cuenta de suscripción OSP.')}{root&&<code>{typeof location!=='undefined'?location.origin:''}/api/webhook</code>}</div></section></>}
{root&&<section className="panel settings-card ai-settings"><div className="section-title"><BookOpen/><div><h2>{t('AI assistant · OpenAI','Asistente IA · OpenAI')}</h2><p>{t('Server-side key. AI charges belong to your OpenAI API account.','Clave en servidor. El consumo IA se cobra a su cuenta OpenAI API.')}</p></div></div><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);run(async()=>{await api('ai-settings',{secret:f.get('secret'),model:f.get('model'),enabled:f.get('enabled')==='on'});await load();msg(t('AI configuration saved','Configuración IA guardada'));});}}><label>{t('OpenAI API key','Clave API OpenAI')}<input name="secret" type="password" autoComplete="new-password" placeholder={me.platformPayment.hasAI?t('Saved securely · leave blank to keep','Guardada · deje vacío para conservar'):'sk-…'}/></label><label>{t('Responses API model ID','ID de modelo Responses API')}<input name="model" defaultValue={me.platformPayment.aiModel||'gpt-4.1-mini'} required/></label><label>{t('Speech transcription model','Modelo para transcribir voz')}<input name="transcriptionModel" defaultValue={me.platformPayment.aiTranscriptionModel||'gpt-transcribe'} required/></label><label className="inline-check"><input name="enabled" type="checkbox" defaultChecked={me.platformPayment.aiEnabled!==false}/>{t('Enable AI answers for active workshops','Habilitar respuestas IA en talleres activos')}</label><button className="primary" disabled={busy}>{t('Save AI configuration','Guardar configuración IA')}</button></form><p className="notice">{t('Without a key, local data and reference search still works. AI receives selected technical context on Send; it cannot access other workshops or payment keys.','Sin clave funciona la búsqueda local de datos y referencias. La IA recibe contexto técnico seleccionado al enviar; no accede a otros talleres ni claves de pago.')}</p></section>}
<section className="panel settings-card"><div className="section-title"><ShieldCheck/><h2>{t('Account security','Seguridad de cuenta')}</h2></div><form onSubmit={e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));run(async()=>{await api('password',f);setMe(null);msg(t('Password updated. Sign in again.','Contraseña actualizada. Ingrese de nuevo.'));});}}><label>{t('Current password','Contraseña actual')}<input name="current" type="password" required autoComplete="current-password"/></label><label>{t('New password (6+ characters)','Nueva contraseña (6+ caracteres)')}<input name="password" type="password" required minLength={6} autoComplete="new-password"/></label><button className="secondary" disabled={busy}>{t('Update password','Actualizar contraseña')}</button></form></section>{manager&&<section className="panel settings-card"><div className="section-title"><Download/><h2>{t('Your data','Sus datos')}</h2></div><p>{t('Download all workshop records as JSON. Passwords and payment secrets are excluded.','Descargue todos los registros en JSON. No incluye contraseñas ni claves secretas de pago.')}</p><button className="secondary" onClick={()=>run(async()=>{const d=await api('export');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download='OSP_AutoCare_Data.json';a.click();URL.revokeObjectURL(a.href);})}><Download size={16}/>{t('Export workshop data','Exportar datos del taller')}</button></section>}</div>}
